self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(FILES)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', event => {
  event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(key => key.startsWith('zilingdao-') && key.endsWith(self.registration.scope) && key !== CACHE).map(key => caches.delete(key)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET' || !event.request.url.startsWith(self.registration.scope)) return;
  event.respondWith(caches.open(CACHE).then(async cache => {
    const url = new URL(event.request.url);
    if (url.pathname.endsWith('/data/wordlist.csv')) {
      try {
        const response = await fetch(event.request, { cache: 'no-store' });
        if (response.ok) { await cache.put(event.request, response.clone()); return response; }
      } catch {}
    }
    const cached = await cache.match(event.request);
    if (cached) return cached;
    try { return await fetch(event.request); }
    catch { return new Response('离线资源未收录', { status: 503 }); }
  }));
});
